struct Node {
    std::shared_ptr<Node> next;
    std::weak_ptr<Node> prev;   // observes, doesn't own
};

auto a = std::make_shared<Node>();
auto b = std::make_shared<Node>();
a->next = b;
b->prev = a;                    // no cycle of owners

if (auto p = b->prev.lock()) {  // shared_ptr, or null
